CustomField.formula:
/*Right(Text(Year(DateValue(Adjusted_Touch_Date_Time__c))), 2)&"-"&*/

if(Month(DateValue(Adjusted_Touch_Date_Time_User__c))>10, Text(Month(DateValue(Adjusted_Touch_Date_Time_User__c))), "0"&Text(Month(DateValue(Adjusted_Touch_Date_Time_User__c))))&"-"&
if(Day(DateValue(Adjusted_Touch_Date_Time_User__c))>10, Text(Day(DateValue(Adjusted_Touch_Date_Time_User__c))), "0"&Text(Day(DateValue(Adjusted_Touch_Date_Time_User__c))))&" | "&

Case(Weekday(DateValue(Adjusted_Touch_Date_Time_User__c)),
1, "SUN ",
2, "MON ",
3, "TUE ",
4, "WED ",
5, "THU ",
6, "FRI ",
7, "SAT ",
"")&

if(Minute(Touch_Time_Only_User__c )<15, if(Hour(Touch_Time_Only_User__c )>9.99, Text(Hour(Touch_Time_Only_User__c )), "0"&Text(Hour(Touch_Time_Only_User__c )))&":00",
if(Minute(Touch_Time_Only_User__c )<30, if(Hour(Touch_Time_Only_User__c )>9.99, Text(Hour(Touch_Time_Only_User__c  )), "0"&Text(Hour(Touch_Time_Only_User__c )))&":15",
if(Minute(Touch_Time_Only_User__c )<45, if(Hour(Touch_Time_Only_User__c  )>9.99, Text(Hour(Touch_Time_Only_User__c  )), "0"&Text(Hour(Touch_Time_Only_User__c )))&":30",
if(Minute(Touch_Time_Only_User__c )<59.999, if(Hour(Touch_Time_Only_User__c )>9.99, Text(Hour(Touch_Time_Only_User__c )), "0"&Text(Hour(Touch_Time_Only_User__c )))&":45",
if(Hour(Touch_Time_Only_User__c )+1>9.99, Text(Hour(Touch_Time_Only_User__c )+1), "0"&Text(Hour(Touch_Time_Only_User__c )+1))&":00")
)))
